Lemma frames_apart_all : forall FSB c c' p q, (c = 0 \/ c = 1 \/ c = 6 \/ c = 2) -> (c' = 0 \/ c' = 1 \/ c' = 6 \/ c' = 2) ->
  0 <= p < NF c -> 0 <= q < NF c' -> (c <> c' \/ p <> q) ->
