Lemma push_pieces :
  FSB + 8 * K + 8 <= FSB + 0x1000 /\ FSB + 0x1000 <= fl_base FSB K + pos /\ fl_base FSB K + pos + 1 <= FSB + 0x9000
  /\ FSB + 0x9000 <= f /\ f + fsz K <= FSB + 0xb09000
  /\ shad FSB <= shad f /\ shad f + fsz K / 8 <= shad (FSB + 0xb09000)
  /\ l_ACEIL L <= usp - 208.
